    type: "national-park",
    parent: "LK-52",
    coords: [81.683, 6.550],
    name: { de: "Kumana-Nationalpark", hu: "Kumana Nemzeti Park", ro: "Parcul Național Kumana", en: "Kumana National Park"},
    image: "/poi-images/kumana-national-park-nature-v2.webp",
    description: { de: "Dieser Park ist bekannt für seine riesigen Schwärme von Zug- und Watvögeln und ein Paradies für Vogelbeobachter.", hu: "A vonuló vízimadarak és gázlómadarak hatalmas csapatainak köszönhetően ez a park a madármegfigyelők igazi paradicsoma.", ro: "Cunoscut pentru stolurile sale masive de păsări migratoare de apă și păsări de țărm, acest parc este un paradis pentru iubitorii de păsări.", en: "Known for its massive flocks of migratory waterfowl and wading birds, this park is a paradise for bird watchers." , es: "Este parque es famoso por sus enormes bandadas de aves migratorias y zancudas, y es un paraíso para los observadores de aves.", pt: "Este parque é famoso pelos seus enormes bandos de aves migratórias e pernaltas, e é um paraíso para os observadores de aves.", fr: "Ce parc est célèbre pour ses énormes nuées d'oiseaux migrateurs et d'échassiers, et est un paradis pour les observateurs d'oiseaux."},
    facts: {
      de: ["Top-Ziel für Vogelbeobachtungen", "Begrenzt durch den Fluss Kumbukkan Oya"],
      hu: ["Kiemelkedő madármegfigyelő hely", "A Kumbukkan Oya folyó határolja"],
      ro: ["Destinație de top pentru observarea păsărilor", "Mărginit de râul Kumbukkan Oya"],
      en: ["Top bird-watching destination", "Bordered by the Kumbukkan Oya river"],
      es: ["Destino principal para la observación de aves", "Limitado por el río Kumbukkan Oya"],
      pt: ["Destino principal para observação de aves", "Limitado pelo rio Kumbukkan Oya"],
      fr: ["Destination principale pour l'observation des oiseaux", "Limité par la rivière Kumbukkan Oya"],
    }, image: "/poi-images/kumana-national-park-nature-v2.webp",
    descriptionAdvanced: {
      de: "Der Kumana-Nationalpark, auch als Yala-Ost-Nationalpark bekannt, liegt an der Südostküste Sri Lankas und ist weltberühmt für seine außergewöhnliche Vogelwelt. Er erstreckt sich über eine Fläche von 35.664 Hektar und beherbergt das Kumana Villu, ein 200 Hektar großes natürliches Sumpfgebiet, das als einer der wichtigsten Brutplätze für Wasservögel im Land gilt. Während der Migrationssaison von Mai bis Juni besuchen Tausende von Vögeln den Park, darunter seltene Arten wie der Buntstorch und der Schwarzhalsstorch. Neben Vögeln bietet der Park auch Lebensraum für größere Säugetiere wie Elefanten, Leoparden und Goldlinsen. Historisch gesehen wurde die Region 1970 als Vogelschutzgebiet ausgewiesen, bevor sie 2006 offiziell den Status eines Nationalparks erhielt. Die Landschaft ist geprägt von Küstenlagunen, Dorngebüschen und weiten Ebenen, was sie zu einem bevorzugten Ziel für Ökotourismus und Naturfotografie macht.",
      hu: "A Kumana Nemzeti Park, más néven Kelet-Yala Nemzeti Park, Srí Lanka délkeleti partvidékén található, és világszerte híres kivételes madárvilágáról. A 35 664 hektáros területen fekszik a Kumana Villu, egy 200 hektáros természetes mocsárvidék, amely az ország egyik legfontosabb vízimadár-szaporodóhelye. A májustól júniusig tartó vonulási szezonban madarak ezrei látogatják a parkot, köztük olyan ritka fajok, mint a festett gólya és a feketenyakú gólya. A madarak mellett a park olyan nagyobb emlősöknek is otthont ad, mint az elefántok, leopárdok és aranysakálok. Történelmileg a területet 1970-ben nyilvánították madárrezervátummá, majd 2006-ban kapott nemzeti parki státuszt. A tájat tengerparti lagúnák, tövises bozótosok és tágas síkságok jellemzik, ami az ökoturizmus és a természetfotózás kedvelt célpontjává teszi.",
      ro: "Parcul Național Kumana, cunoscut și sub numele de Parcul Național Yala Est, este situat pe coasta de sud-est a Sri Lankăi și este renumit la nivel mondial pentru avifauna sa excepțională. Întins pe o suprafață de 35.664 de hectare, parcul adăpostește Kumana Villu, o mlaștină naturală de 200 de hectare, considerată unul dintre cele mai importante locuri de cuibărit pentru păsările acvatice din țară. În timpul sezonului de migrație, din mai până în iunie, mii de păsări vizitează parcul, inclusiv specii rare precum barza vopsită și barza cu gât negru. Pe lângă păsări, parcul oferă habitat pentru mamifere mari, cum ar fi elefanții, leoparzii și șacalii aurii. Istoric, regiunea a fost declarată sanctuar de păsări în 1970, înainte de a primi statutul oficial de parc național în 2006. Peisajul este marcat de lagune de coastă și câmpii vaste, fiind o destinație preferată pentru ecoturism.",
      en: "Kumana National Park, also known as Yala East National Park, is located on the southeastern coast of Sri Lanka and is world-renowned for its exceptional birdlife. Spanning an area of 35,664 hectares, it houses the Kumana Villu, a 200-hectare natural swamp that is considered one of the most important breeding grounds for waterbirds in the country. During the migration season from May to June, thousands of birds visit the park, including rare species like the painted stork and the black-necked stork. Besides birds, the park provides habitat for larger mammals such as elephants, leopards, and golden jackals. Historically, the region was designated as a bird sanctuary in 1970 before officially receiving national park status in 2006. The landscape is characterized by coastal lagoons, thorn bushes, and vast plains, making it a preferred destination for ecotourism and nature photography.",
      es: "El Parque Nacional Kumana, anteriormente Yala Este, se encuentra en la zona seca oriental de Sri Lanka. Fue declarado parque nacional en 2006 y abarca 181 km². El parque es conocido por su avifauna, especialmente aves acuáticas como pelícanos y garzas; el Santuario de Aves de Kumana se encuentra dentro del parque. La vegetación consiste en bosques secos, lagunas y humedales. El parque es también hogar de elefantes y leopardos. El sistema de Kumana es una importante zona de cría para aves migratorias.",
      pt: "O Parque Nacional Kumana, anteriormente Yala Este, encontra-se na zona seca oriental do Sri Lanka. Foi declarado parque nacional em 2006 e abrange 181 km². O parque é conhecido pela sua avifauna, especialmente aves aquáticas como pelicanos e garças; o Santuário de Aves de Kumana encontra-se dentro do parque. A vegetação consiste em florestas secas, lagoas e zonas húmidas. O parque é também lar de elefantes e leopardos. O sistema de Kumana é uma importante área de nidificação para aves migratórias.",
      fr: "Le parc national de Kumana, anciennement Yala Est, se trouve dans la zone sèche orientale du Sri Lanka. Il a été déclaré parc national en 2006 et couvre 181 km². Le parc est connu pour son avifaune, notamment les oiseaux aquatiques comme les pélicans et les hérons ; le sanctuaire d'oiseaux de Kumana se trouve à l'intérieur du parc. La végétation se compose de forêts sèches, de lagunes et de zones humides. Le parc abrite également des éléphants et des léopards. Le système de Kumana est une importante zone de nidification pour les oiseaux migrateurs.",
    },
