      de: ["Der Park erstreckt sich über eine Gesamtfläche von 35.664 Hektar.", "Das Kumana Villu Sumpfgebiet ist etwa 200 Hektar groß.", "Über 255 verschiedene Vogelarten wurden im Park dokumentiert.", "Der seltene Schwarzhalsstorch brütet regelmäßig in diesem Gebiet.", "Die Region erhielt im Jahr 2006 den Status eines Nationalparks.", "Der Park liegt etwa 390 Kilometer südöstlich von der Hauptstadt Colombo."],
      hu: ["A nemzeti park teljes területe 35 664 hektár.", "A Kumana Villu mocsárvidék kiterjedése 200 hektár.", "A parkban több mint 255 madárfajt jegyeztek fel eddig.", "Itt található Srí Lanka egyik legfontosabb festett gólya fészkelőhelye.", "A terület 2006-ban kapta meg a nemzeti parki minősítést.", "A park Colombo városától körülbelül 390 kilométerre fekszik."],
      ro: ["Parcul se întinde pe o suprafață totală de 35.664 de hectare.", "Mlaștina Kumana Villu are o suprafață de aproximativ 200 de hectare.", "Peste 255 de specii de păsări au fost documentate în interiorul parcului.", "Barza cu gât negru, o specie rară, poate fi observată frecvent aici.", "Regiunea a fost declarată oficial parc național în anul 2006.", "Parcul este situat la aproximativ 390 de kilometri distanță de Colombo."],
      en: ["The park covers a total land area of 35,664 hectares.", "The Kumana Villu swamp area covers about 200 hectares.", "Over 255 different species of birds have been documented in the park.", "The rare black-necked stork is known to breed in this protected area.", "The region officially attained national park status in 2006.", "The park is located approximately 390 kilometers southeast of Colombo."],
      es: ["El parque fue declarado parque nacional en 2006.", "La superficie es de 181 km².", "El santuario de aves alberga millones de aves reproductoras.", "Existen más de 200 especies de aves.", "Las lagunas cubren 30 km².", "La población de elefantes se estima en 100–150 animales."],
      pt: ["O parque foi declarado parque nacional em 2006.", "A área é de 181 km².", "O santuário de aves abriga milhões de aves reprodutoras.", "Existem mais de 200 espécies de aves.", "As lagoas cobrem 30 km².", "A população de elefantes é estimada em 100–150 animais."],
