    description: { de: "Es wurde hauptsächlich zum Schutz des Einzugsgebietes des Lunugamvehera-Stausees und als Korridor für Elefanten eingerichtet.", hu: "Elsősorban a Lunugamvehera-víztározó vízgyűjtő területének védelmére és fontos elefántfolyosóként hozták létre.", ro: "Înființat în principal pentru a proteja bazinul hidrografic al rezervorului Lunugamvehera și pentru a servi drept coridor pentru elefanți.", en: "Established primarily to protect the catchment area of the Lunugamvehera reservoir and to serve as a corridor for elephants." , es: "Se estableció principalmente para proteger el área de captación del embalse de Lunugamvehera y como corredor para los elefantes.", pt: "Foi estabelecido principalmente para proteger a área de captação da albufeira de Lunugamvehera e como corredor para elefantes.", fr: "Il a été établi principalement pour protéger le bassin versant du réservoir de Lunugamvehera et comme corridor pour les éléphants."},
